const player={x:W/2,target:W/2,y:465,w:108,h:68,speed:690};
try{best=Number(localStorage.getItem('starCatcherBest'))||0}catch(e){} bestEl.textContent=best;
const rand=(a,b)=>a+Math.random()*(b-a);
