function updateHud(){scoreEl.textContent=String(score).padStart(3,'0');level=Math.floor(score/10)+1;levelEl.textContent=level;livesEl.innerHTML=[0,1,2].map(i=>`<span class="${i>=lives?'lost':''}">❤️</span>`).join('')}
function endGame(){state='over';pauseBtn.disabled=true;overlay.classList.remove('hidden');$('dialogEmoji').textContent='💫';$('dialogTitle').textContent='سالاو القلوب!';$('dialogText').textContent=`جمعتي ${score} ${score===1?'نقطة':'نقاط'} — واش تقدر تحطم رقمك القياسي؟`;playBtn.textContent='عاود اللعب';if(score>best){best=score;bestEl.textContent=best;try{localStorage.setItem('starCatcherBest',best)}catch(e){}}}
function pause(){if(state==='playing'){state='paused';pauseBtn.textContent='▶';$('dialogEmoji').textContent='⏸️';$('dialogTitle').textContent='وقفنا شوية';$('dialogText').textContent='السلة ديالك محتافظا بمكانها. واجد تكمل؟';playBtn.textContent='كمّل اللعب';overlay.classList.remove('hidden')}else if(state==='paused'){state='playing';pauseBtn.textContent='Ⅱ';overlay.classList.add('hidden')}}
playBtn.addEventListener('click',()=>state==='paused'?pause():start());pauseBtn.addEventListener('click',pause);
window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight',' ','Escape'].includes(e.key))e.preventDefault();keys[e.key]=true;if((e.key===' '||e.key==='Escape')&&state==='playing')pause();else if((e.key===' '||e.key==='Enter')&&(state==='ready'||state==='over'))start()});window.addEventListener('keyup',e=>keys[e.key]=false);window.addEventListener('blur',()=>{keys={};if(state==='playing')pause()});
function setTarget(e){const r=canvas.getBoundingClientRect();player.target=Math.max(52,Math.min(W-52,(e.clientX-r.left)*W/r.width))}
canvas.addEventListener('pointerdown',e=>{if(state==='playing'){setTarget(e);canvas.setPointerCapture?.(e.pointerId)}});canvas.addEventListener('pointermove',e=>{if(state==='playing'&&(e.pointerType==='mouse'||e.buttons))setTarget(e)});
