function spawn(){const hazard=Math.random()<Math.min(.24,.13+(level-1)*.012);items.push({x:rand(34,W-34),y:-35,r:hazard?rand(20,25):rand(16,21),vy:rand(190,270)+level*22,rot:rand(0,6.28),spin:rand(-2.2,2.2),type:hazard?(Math.random()<.54?'bomb':'rock'):(Math.random()<.68?'star':'coin'),phase:rand(0,6.28)})}
function burst(x,y,color,n=12){for(let i=0;i<n;i++){const a=rand(0,Math.PI*2),v=rand(55,220);particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:rand(.35,.8),max:.8,color,size:rand(2,5)})}}
function update(dt){elapsed+=dt;if(state==='playing'){
 let direction=(keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0);if(direction)player.target=Math.max(52,Math.min(W-52,player.target+direction*player.speed*dt));player.x+=(player.target-player.x)*Math.min(1,dt*13);player.x=Math.max(52,Math.min(W-52,player.x));
 spawnTimer-=dt;if(spawnTimer<=0){spawn();spawnTimer=Math.max(.31,.82-(level-1)*.035)+rand(0,.35)}
 for(let i=items.length-1;i>=0;i--){const o=items[i];o.y+=o.vy*dt;o.rot+=o.spin*dt;o.phase+=dt*4;
  if(Math.abs(o.x-player.x)<player.w*.43+o.r*.48&&o.y+o.r>player.y-15&&o.y-o.r<player.y+player.h*.42){
   if(o.type==='bomb'||o.type==='rock'){if(!player.hitUntil||elapsed>player.hitUntil){lives--;player.hitUntil=elapsed+1.25;shake=.35;burst(o.x,o.y,'#ff778e',17);updateHud();if(lives<=0)endGame()}}else{score+=o.type==='star'?1:2;burst(o.x,o.y,o.type==='star'?'#ffde81':'#63e5d4',9);updateHud()}items.splice(i,1);continue}
