 const floor=ctx.createLinearGradient(0,460,0,H);floor.addColorStop(0,'#342b55');floor.addColorStop(1,'#1c2041');ctx.fillStyle=floor;ctx.fillRect(0,468,W,72);ctx.strokeStyle='#ffcf7040';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,468);ctx.lineTo(W,468);ctx.stroke();
}
