function drawItem(o){ctx.save();ctx.translate(o.x,o.y);ctx.rotate(o.rot);const glow=ctx.createRadialGradient(0,0,2,0,0,o.r*2.3);glow.addColorStop(0,o.type==='bomb'||o.type==='rock'?'#ff778e35':'#ffdc783d');glow.addColorStop(1,'#ffffff00');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(0,0,o.r*2.3,0,Math.PI*2);ctx.fill();
 if(o.type==='star'){const g=ctx.createLinearGradient(-o.r,-o.r,o.r,o.r);g.addColorStop(0,'#fff5b8');g.addColorStop(.5,'#ffcf55');g.addColorStop(1,'#f49d48');ctx.fillStyle=g;ctx.shadowColor='#ffd15a';ctx.shadowBlur=15;starPath(0,0,o.r,o.r*.46);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#fff9d8';ctx.beginPath();ctx.arc(-4,-6,2.5,0,Math.PI*2);ctx.fill()}
 else if(o.type==='coin'){ctx.shadowColor='#ffcf55';ctx.shadowBlur=14;const g=ctx.createLinearGradient(-o.r,0,o.r,0);g.addColorStop(0,'#d98737');g.addColorStop(.25,'#ffe584');g.addColorStop(.65,'#ffbd42');g.addColorStop(1,'#f18d32');ctx.fillStyle=g;ctx.beginPath();ctx.ellipse(0,0,o.r*.77,o.r,0,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#fff0a6';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,0,o.r*.48,o.r*.72,0,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#fff0a6';ctx.font='bold 14px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('✦',0,1)}
